#!/usr/bin/env node

import { access, cp, mkdir, readFile, rm, writeFile } from 'node:fs/promises'
import path from 'node:path'
import process from 'node:process'
import { Script } from 'node:vm'

const sourceDirectory = path.resolve(process.argv[2] || 'dist')
const outputDirectory = path.resolve(process.argv[3] || '.lavish/app-review')
const sourceIndex = path.join(sourceDirectory, 'index.html')
const outputIndex = path.join(outputDirectory, 'index.html')
// Marks a directory as generated by this script, so pruning stale output on
// rebuild can never delete a directory the workshop did not create.
const artifactMarker = path.join(outputDirectory, '.lavish-review-artifact')
const storageCompatibilityScript = await readFile(
  new URL('./lavish-storage-compat.js', import.meta.url),
  'utf8',
)

const outputWithinSource = path.relative(sourceDirectory, outputDirectory)
if (outputWithinSource === '' || (!outputWithinSource.startsWith('..') && !path.isAbsolute(outputWithinSource))) {
  throw new Error('The Lavish review output directory must be outside the Vite build directory.')
}

function attributeValue(attributes, name) {
  const match = attributes.match(new RegExp(`\\b${name}\\s*=\\s*(["'])(.*?)\\1`, 'i'))
  return match?.[2] ?? null
}

function isJavaScript(attributes) {
  const type = attributeValue(attributes, 'type')
  return type === null || type === 'module' || /^(?:text|application)\/javascript$/i.test(type)
}

function isRemoteOrEmbeddedReference(reference) {
  return reference.startsWith('//') || /^[a-z][a-z\d+.-]*:/i.test(reference)
}

function resolveLocalAsset(reference, baseDirectory = sourceDirectory) {
  if (!reference || reference.startsWith('//') || /^[a-z][a-z\d+.-]*:/i.test(reference)) {
    throw new Error(`Review assets must be local build files: ${reference || '(missing reference)'}`)
  }

  const cleanReference = reference.split(/[?#]/, 1)[0]
  let decodedReference
  try {
    decodedReference = decodeURIComponent(cleanReference)
  } catch {
    throw new Error(`Review asset has an invalid encoded path: ${reference}`)
  }
  const rootedReference = decodedReference.startsWith('/')
  const relativeReference = rootedReference ? decodedReference.slice(1) : decodedReference
  const resolved = path.resolve(rootedReference ? sourceDirectory : baseDirectory, relativeReference)
  const relative = path.relative(sourceDirectory, resolved)
  if (relative.startsWith('..') || path.isAbsolute(relative)) {
    throw new Error(`Review asset escapes the build directory: ${reference}`)
  }
  return resolved
}

function mimeTypeForAsset(file) {
  const extension = path.extname(file).toLowerCase()
  return {
    '.avif': 'image/avif',
    '.eot': 'application/vnd.ms-fontobject',
    '.gif': 'image/gif',
    '.ico': 'image/x-icon',
    '.jpeg': 'image/jpeg',
    '.jpg': 'image/jpeg',
    '.otf': 'font/otf',
    '.png': 'image/png',
    '.svg': 'image/svg+xml',
    '.ttf': 'font/ttf',
    '.webp': 'image/webp',
    '.woff': 'font/woff',
    '.woff2': 'font/woff2',
  }[extension] || 'application/octet-stream'
}

function assertClassicBundle(source, reference) {
  const moduleSyntax = [
    /\bimport\s*\(/,
    /\bimport\.meta\b/,
    /(^|[;}\n])\s*import\s*(?:["'{*]|[\w$]+\s*(?:,|from))/m,
    /(^|[;}\n])\s*export\s+(?:default|const|let|var|function|class|\{|\*)/m,
  ]
  if (moduleSyntax.some((pattern) => pattern.test(source))) {
    throw new Error(
      `Cannot make ${reference} sandbox-safe because it still contains module imports or exports. ` +
      'Disable code splitting or use a single-file Vite build before preparing the review.',
    )
  }

  try {
    new Script(source)
  } catch (error) {
    throw new Error(
      `Cannot make ${reference} sandbox-safe because it is not valid as a classic script: ${error.message}`,
    )
  }
}

function safeInlineScript(source) {
  return source.replace(/<\/script/gi, '<\\/script')
}

function safeInlineStyle(source) {
  return source.replace(/<\/style/gi, '<\\/style')
}

assertClassicBundle(storageCompatibilityScript, 'the Lavish Web Storage compatibility helper')

async function inlineStylesheetAssets(source, stylesheetFile) {
  const assetPattern = /url\(\s*(?:(["'])(.*?)\1|([^)'"\s][^)]*?))\s*\)/gi
  return replaceAsync(source, assetPattern, async (fullMatch, _quote, quotedReference, bareReference) => {
    const reference = String(quotedReference ?? bareReference ?? '').trim()
    if (!reference || reference.startsWith('#') || isRemoteOrEmbeddedReference(reference)) return fullMatch

    const assetFile = resolveLocalAsset(reference, path.dirname(stylesheetFile))
    const asset = await readFile(assetFile)
    const fragmentIndex = reference.indexOf('#')
    const fragment = fragmentIndex >= 0 ? reference.slice(fragmentIndex) : ''
    return `url("data:${mimeTypeForAsset(assetFile)};base64,${asset.toString('base64')}${fragment}")`
  })
}

async function inlineViteBundleAssets(source, bundleFile) {
  // Vite inlines small assets as data: URIs itself but still wraps them in
  // new URL(..., import.meta.url); a data: URL is already absolute, so the
  // wrapper resolves to the URI itself. Unwrap it so no import.meta remains.
  const inlinedDataUrlPattern = /new URL\(\s*([`"'])(data:[^`"']*)\1\s*,\s*import\.meta\.url\s*\)\.href/gi
  source = source.replace(inlinedDataUrlPattern, (_fullMatch, _quote, dataUri) => JSON.stringify(dataUri))

  const assetPattern = /new URL\(\s*([`"'])([a-z\d_./%+@~?#=&-]+)\1\s*,\s*import\.meta\.url\s*\)\.href/gi
  return replaceAsync(source, assetPattern, async (_fullMatch, _quote, reference) => {
    const assetFile = resolveLocalAsset(reference, path.dirname(bundleFile))
    const asset = await readFile(assetFile)
    const fragmentIndex = reference.indexOf('#')
    const fragment = fragmentIndex >= 0 ? reference.slice(fragmentIndex) : ''
    return JSON.stringify(`data:${mimeTypeForAsset(assetFile)};base64,${asset.toString('base64')}${fragment}`)
  })
}

function assertNoLocalStylesheetImports(source, reference) {
  const importPattern = /@import\s+(?:url\(\s*)?(?:(["'])(.*?)\1|([^\s;)]+))/gi
  for (const match of source.matchAll(importPattern)) {
    const importedReference = String(match[2] ?? match[3] ?? '').trim()
    if (importedReference && !isRemoteOrEmbeddedReference(importedReference)) {
      throw new Error(
        `Cannot make ${reference} sandbox-safe because it still contains a local CSS @import. ` +
        'Ensure the Vite build bundles stylesheet imports before preparing the review.',
      )
    }
  }
}

let html
try {
  html = await readFile(sourceIndex, 'utf8')
} catch (error) {
  console.error(`Could not read the Vite build entry at ${sourceIndex}.`)
  console.error('Run workshop/scripts/lavish-review open <project-dir> from the workshop repository root.')
  throw error
}

let inlinedStylesheetCount = 0
const stylesheetPattern = /<link\b([^>]*)>/gi
html = await replaceAsync(html, stylesheetPattern, async (fullMatch, attributes) => {
  const relation = attributeValue(attributes, 'rel')
  if (!relation?.split(/\s+/).some((value) => value.toLowerCase() === 'stylesheet')) return fullMatch

  const reference = attributeValue(attributes, 'href')
  if (!reference || isRemoteOrEmbeddedReference(reference)) return fullMatch

  const stylesheetFile = resolveLocalAsset(reference)
  let source = await readFile(stylesheetFile, 'utf8')
  assertNoLocalStylesheetImports(source, reference)
  source = await inlineStylesheetAssets(source, stylesheetFile)
  inlinedStylesheetCount += 1

  const media = attributeValue(attributes, 'media')
  const mediaAttribute = media ? ` media=${JSON.stringify(media)}` : ''
  return `<style data-lavish-inline="vite-style"${mediaAttribute}>\n${safeInlineStyle(source)}\n    </style>`
})

const queuedScripts = []
const scriptPattern = /<script\b([^>]*)>([\s\S]*?)<\/script\s*>/gi
html = await replaceAsync(html, scriptPattern, async (fullMatch, attributes, inlineSource) => {
  if (!isJavaScript(attributes)) return fullMatch

  const reference = attributeValue(attributes, 'src')
  const bundleFile = reference ? resolveLocalAsset(reference) : null
  let source = bundleFile ? await readFile(bundleFile, 'utf8') : inlineSource
  if (bundleFile) source = await inlineViteBundleAssets(source, bundleFile)
  assertClassicBundle(source, reference || 'an inline module')
  queuedScripts.push(safeInlineScript(source))
  return ''
})

if (queuedScripts.length === 0) {
  throw new Error('The Vite build entry contains no JavaScript application bundle.')
}
if (!/<\/body\s*>/i.test(html)) {
  throw new Error('The Vite build entry has no closing body tag.')
}

const compatibilityScript =
  `    <script data-lavish-inline="storage-compat">\n${safeInlineScript(storageCompatibilityScript)}\n    </script>`
const applicationScripts = queuedScripts
  .map((source) => `    <script data-lavish-inline="vite-bundle">\n${source}\n    </script>`)
  .join('\n')
const scripts = `${compatibilityScript}\n${applicationScripts}`
const closingBodyMatches = [...html.matchAll(/<\/body\s*>/gi)]
const closingBody = closingBodyMatches.at(-1)
const closingBodyIndex = closingBody?.index
if (closingBodyIndex === undefined) {
  throw new Error('The Vite build entry has no closing body tag.')
}

// Do not pass a minified bundle as String.replace's replacement string. Tokens
// such as $`, $&, and $' inside ordinary JavaScript would be interpreted and
// silently inject pieces of the HTML document into the application bundle.
html = `${html.slice(0, closingBodyIndex)}${scripts}\n  ${html.slice(closingBodyIndex)}`

// The finished artifact must be self-contained. A nested iframe or an
// embedded development/forwarded URL is exactly the class of review that
// renders as a trust page, a blank screen, or a dead click surface.
const forbiddenArtifactPatterns = [
  [/<iframe\b/i, 'an <iframe> element'],
  [/(?:https?:)?\/\/(?:localhost|127\.0\.0\.1|0\.0\.0\.0)(?::\d+)?/i, 'a localhost or loopback URL'],
  [/[a-z0-9-]+\.app\.github\.dev/i, 'a Codespaces forwarded URL'],
]
for (const [pattern, description] of forbiddenArtifactPatterns) {
  if (pattern.test(html)) {
    throw new Error(
      `The prepared review artifact contains ${description}. Review artifacts must be ` +
      'self-contained: remove the embedded frame or URL from the application entry page.',
    )
  }
}

// Prune stale output (hashed asset bundles accumulate across rebuilds), but
// only ever delete a directory this script marked as its own.
const outputExists = await access(outputDirectory).then(() => true, () => false)
if (outputExists) {
  const markerExists = await access(artifactMarker).then(() => true, () => false)
  if (!markerExists) {
    throw new Error(
      `Refusing to overwrite ${outputDirectory}: it was not generated by this script. ` +
      'Move or delete it, then rerun the review command.',
    )
  }
  await rm(outputDirectory, { recursive: true, force: true })
}
await mkdir(outputDirectory, { recursive: true })
await cp(sourceDirectory, outputDirectory, { recursive: true, force: true })
await writeFile(outputIndex, html, 'utf8')
await writeFile(artifactMarker, 'generated by workshop/scripts/prepare-lavish-vite.mjs\n', 'utf8')

console.log(
  `Prepared sandbox-safe Lavish review: ${outputIndex} ` +
  `(${inlinedStylesheetCount} stylesheet(s), ${queuedScripts.length} script(s) inlined)`,
)

async function replaceAsync(value, pattern, replacer) {
  const matches = [...value.matchAll(pattern)]
  if (matches.length === 0) return value

  let result = ''
  let cursor = 0
  for (const match of matches) {
    result += value.slice(cursor, match.index)
    result += await replacer(...match)
    cursor = match.index + match[0].length
  }
  return result + value.slice(cursor)
}
